insert into public.writing_grammar_rules (corpus_version, rule_id, title_zh_hant, grammar_category, formula, structural_signature, incorrect_pattern, correct_pattern, explanation_zh_hant, correct_examples, incorrect_examples, alternative_corrections, english_variant, status, author, version)
select '2026-08-02.1', 'CLAUSE_NOT_ONLY_INITIAL_INVERSION', '文法規則：CLAUSE NOT_ONLY INITIAL_INVERSION', 'sentence_structure', 'CLAUSE.NOT_ONLY.INITIAL_INVERSION', '["clause","not_only","initial_inversion"]'::jsonb, 'Not only several contractors failed', 'Not only did several contractors fail', 'Not only 放在句首並修飾整個分句時，要使用助動詞倒裝：Not only + did + 主語 + 動詞原形。邊界： Not only the contractors but also the engineers agreed 中， not only 只連接名詞詞組，因此不用倒裝。', '["Not only did several contractors fail"]'::jsonb, '["Not only several contractors failed"]'::jsonb, '[]'::jsonb, 'British English', 'approved', 'Edmund Sir', 1
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_rules (corpus_version, rule_id, title_zh_hant, grammar_category, formula, structural_signature, incorrect_pattern, correct_pattern, explanation_zh_hant, correct_examples, incorrect_examples, alternative_corrections, english_variant, status, author, version)
select '2026-08-02.1', 'CLAUSE_NOT_UNTIL_INITIAL_MAIN_INVERSION', '文法規則：CLAUSE NOT_UNTIL INITIAL_MAIN_INVERSION', 'sentence_structure', 'CLAUSE.NOT_UNTIL.INITIAL_MAIN_INVERSION', '["clause","not_until","initial_main_inversion"]'::jsonb, 'Not until the exhibition opened residents realised', 'Not until the exhibition opened did residents realise', 'Not until + 分句放在句首時，後面的主句要使用助動詞倒裝： did + 主語 + 動詞原形。若放在句尾，則不用倒裝： Residents did not realise it until the exhibition opened.', '["Not until the exhibition opened did residents realise"]'::jsonb, '["Not until the exhibition opened residents realised"]'::jsonb, '[]'::jsonb, 'British English', 'approved', 'Edmund Sir', 1
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_rules (corpus_version, rule_id, title_zh_hant, grammar_category, formula, structural_signature, incorrect_pattern, correct_pattern, explanation_zh_hant, correct_examples, incorrect_examples, alternative_corrections, english_variant, status, author, version)
select '2026-08-02.1', 'CLAUSE_NO_SOONER_PAST_PERFECT_INVERSION', '文法規則：CLAUSE NO_SOONER PAST_PERFECT_INVERSION', 'sentence_structure', 'CLAUSE.NO_SOONER.PAST_PERFECT_INVERSION', '["clause","no_sooner","past_perfect_inversion"]'::jsonb, 'No sooner the investigators had', 'No sooner had the investigators', 'No sooner 放在句首時，要使用過去完成式倒裝：No sooner + had + 主語 + 過去分詞。', '["No sooner had the investigators"]'::jsonb, '["No sooner the investigators had"]'::jsonb, '[]'::jsonb, 'British English', 'approved', 'Edmund Sir', 1
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_rules (corpus_version, rule_id, title_zh_hant, grammar_category, formula, structural_signature, incorrect_pattern, correct_pattern, explanation_zh_hant, correct_examples, incorrect_examples, alternative_corrections, english_variant, status, author, version)
select '2026-08-02.1', 'CLAUSE_NO_STAFF_BE_PROGRESSIVE_ARTICLE', '文法規則：CLAUSE NO_STAFF BE_PROGRESSIVE ARTICLE', 'sentence_structure', 'CLAUSE.NO_STAFF.BE_PROGRESSIVE.ARTICLE', '["clause","no_staff","be_progressive","article"]'::jsonb, 'wearing uniform', 'are wearing a uniform', '關係分句需要有限動詞，所以在 wearing 前加入 are。 uniform 是單數可數名詞，前面需要冠詞 a。本句把 staff 視為多名員工，因此使用 are。', '["are wearing a uniform"]'::jsonb, '["wearing uniform"]'::jsonb, '[]'::jsonb, 'British English', 'approved', 'Edmund Sir', 1
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_rules (corpus_version, rule_id, title_zh_hant, grammar_category, formula, structural_signature, incorrect_pattern, correct_pattern, explanation_zh_hant, correct_examples, incorrect_examples, alternative_corrections, english_variant, status, author, version)
select '2026-08-02.1', 'CLAUSE_ONLY_AFTER_INITIAL_INVERSION', '文法規則：CLAUSE ONLY_AFTER INITIAL_INVERSION', 'sentence_structure', 'CLAUSE.ONLY_AFTER.INITIAL_INVERSION', '["clause","only_after","initial_inversion"]'::jsonb, 'the panel ruled', 'did the panel rule', 'Only after + 分句放在句首時，主句要倒裝： Only after… did + 主語 + 動詞原形。若 only after 放在句尾，則不用倒裝：The panel ruled out fraud only after examining the records。', '["did the panel rule"]'::jsonb, '["the panel ruled"]'::jsonb, '[]'::jsonb, 'British English', 'approved', 'Edmund Sir', 1
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
