insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0008-I010', 'I010', 'PARA-0008-S05', 3, 'might have avoided', 'might have been avoided', 1, 'MODAL_PERFECT_PASSIVE_HAVE_BEEN_PARTICIPLE', '「might have avoided」在此應改為「might have been avoided」。treatment 是「本來可能被避免」的事物，所以用完成式被動語態：might have been + 過去分詞。 The hospital might have avoided the expense 才是主動結構。', '[]'::jsonb, 0.9, 'approved'
