insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0008-I024', 'I024', 'PARA-0008-S12', 1, 'providing', 'provide', 1, 'PARALLEL_SHARED_TO_INFINITIVE_BASE_VERBS', '「providing」在此應改為「provide」。to 同時控制後面的並列動詞，所以各項都使用動詞原形： to improve, provide, support, and promote。若改用 used for，整組才可使用動名詞。', '[]'::jsonb, 0.9, 'approved'
