insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0008-I025', 'I025', 'PARA-0008-S12', 2, 'wide', 'widely', 1, 'WORDFORM_MANNER_ADVERB_AFTER_VERB', '「wide」在此應改為「widely」。widely 是副詞，在這裡修飾 shared，表示利益廣泛地被分享。 wide 可在 open wide 或 far and wide 等結構中作副詞，但本句需要 widely。', '[]'::jsonb, 0.9, 'approved'
