insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0008-I026', 'I026', 'PARA-0008-S12', 3, 'reserve', 'reserved', 1, 'PARALLEL_RATHER_THAN_PASSIVE_PARTICIPLES', '「reserve」在此應改為「reserved」。shared 和 reserved 都由前面的 are 控制，兩者應同為過去分詞。也可寫 are shared widely rather than being reserved。', '[]'::jsonb, 0.9, 'approved'
