insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0008-I029', 'I029', 'PARA-0008-S13', 1, 'remain healthily, productivity, and independently', 'remain healthy, productive, and independent', 1, 'LINKING_REMAIN_ADJECTIVE_COMPLEMENTS', '「remain healthily, productivity, and independently」在此應改為「remain healthy, productive, and independent」。remain 是連繫動詞，後面使用形容詞描述 citizens 的狀態。三項亦要保持平行： healthy, productive, and independent。副詞通常修飾動作，而不是在這裡描述主語。', '[]'::jsonb, 0.9, 'approved'
