insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0008-I032', 'I032', 'PARA-0008-S14', 3, 'lowering', 'lowers', 1, 'PARALLEL_FINITE_VERBS_SHARED_SUBJECT', '「lowering」在此應改為「lowers」。主語 it 同時控制三個並列的一般現在式動詞： reduces, lowers, and protects。 lowering 可在另一種結構中成立，例如 It reduces suffering, thereby lowering pressure on hospitals.', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0008-I033', 'I033', 'PARA-0008-S14', 4, 'to', 'on', 1, 'PREP_PRESSURE_ON_SYSTEM', '「to」在此應改為「on」。表示某個系統承受負擔，用 pressure on + 系統／人。 pressure to do something 則表示做某事的壓力，例如 pressure to reduce costs。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0008-I034', 'I034', 'PARA-0008-S15', 1, 'Although treating', 'Treating', 1, 'CONJ_ALTHOUGH_NO_COORDINATING_BUT', '「Although treating」在此應改為「Treating」。although 和 but 不應同時連接同一對分句。可寫 Although treating illness matters, preventing it is wiser，或像目標句一樣寫 Treating illness matters, but...。', '[]'::jsonb, 0.9, 'approved'
