insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0008-I036', 'I036', 'PARA-0008-S15', 3, 'for', 'of', 1, 'COLLOC_USE_OF_PUBLIC_MONEY', '「for」在此應改為「of」。表示「公共資金的運用」，用 the use of public money。 money for treatment 可以成立，但那表示撥作治療用途的資金，結構和意思不同。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0009-I001', 'I001', 'PARA-0009-S01', 1, 'many employers', 'many employees', 1, 'WORDCHOICE_EMPLOYEE_AFFECTED_WORKER_NOT_EMPLOYER', '「many employers」在此應改為「many employees」。employer 是僱主， employee 是僱員。下文說這些人的僱主在非工作時間給他們工作，因此原意很可能是 employees。不過這項修改涉及人物角色，系統應先根據上下文判斷，不宜只靠單句自動更改。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0009-I002', 'I002', 'PARA-0009-S01', 2, 'blame on the phenomenon', 'complain about the phenomenon', 1, 'VERB_COMPLAIN_ABOUT_PROBLEM', '「blame on the phenomenon」在此應改為「complain about the phenomenon」。如果原意是「抱怨某個問題」，用 complain about + 問題。 blame 的結構不同： blame someone for something 或 blame something on someone。由於更換動詞可能改變意思，建議老師確認。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0009-I003', 'I003', 'PARA-0009-S01', 3, 'during holiday', 'during holidays', 1, 'NOUN_RECURRING_HOLIDAY_PLURAL', '「during holiday」在此應改為「during holidays」。這裡泛指多次假期，而不是某一個特定假期，所以用複數 holidays。若指一個特定假期，可寫 during the holiday。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0009-I004', 'I004', 'PARA-0009-S01', 4, 'offer jobs for them', 'give them work', 1, 'COLLOC_GIVE_PERSON_WORK', '「offer jobs for them」在此應改為「give them work」。offer someone a job 通常表示提供一個職位；本句則指僱主在下班後給員工工作，所以可寫 give them work。 另一個正確寫法是 assign work to them。 這項修改涉及 job 和 work 的意思差別，宜保留老師覆核。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0009-I005', 'I005', 'PARA-0009-S01', 5, 'apart from working hours', 'outside working hours', 1, 'PREP_OUTSIDE_WORKING_HOURS', '「apart from working hours」在此應改為「outside working hours」。表示「在工作時間以外」，用 outside working hours。 apart from 通常表示「除…… 之外」或「除了」，例如 Apart from Sunday, the office is open every day.', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0009-I006', 'I006', 'PARA-0009-S02', 1, 'highly believe', 'strongly believe', 1, 'COLLOC_STRONGLY_BELIEVE', '「highly believe」在此應改為「strongly believe」。表示相信程度很高，標準搭配是 strongly believe。 highly 常修飾 successful、 unlikely、 recommended 等詞； highly believe 並非一般標準搭配。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0009-I007', 'I007', 'PARA-0009-S02', 2, 'has placed detrimental effects on', 'has had detrimental effects on', 1, 'COLLOC_HAVE_EFFECTS_ON', '「has placed detrimental effects on」在此應改為「has had detrimental effects on」。表示某事對某人產生影響，可用 have an effect on 或 have effects on。 所以這裡寫 has had detrimental effects on workers。另一個正確結構是 has placed considerablepressure on workers，但不能混合兩個搭配。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0009-I008', 'I008', 'PARA-0009-S04', 1, 'offer job duties', 'assign duties', 1, 'COLLOC_ASSIGN_DUTIES', '「offer job duties」在此應改為「assign duties」。工作任務通常由僱主 assign，所以用 assign duties。offer a job 是提供職位； offer help 是提供協助，與分派職責不同。', '[]'::jsonb, 0.9, 'approved'
