select '2026-08-02.1', 'PARA-0009-I018', 'I018', 'PARA-0009-S08', 3, ', and which', ', which', 1, 'CLAUSE_NONRESTRICTIVE_WHICH_NO_COORDINATING_AND', '「, and which」在此應改為「, which」。which may boost... 是補充前面整個結果的非限制性關係分句。前面已有逗號連接，因此不再加入 and。 另一個正確寫法是分成兩個主句：..., and this may boost their anxiety.', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0009-I019', 'I019', 'PARA-0009-S09', 1, '247', '24/7', 1, 'ORTHOGRAPHY_TWENTY_FOUR_SEVEN_SLASH', '「247」在此應改為「24/7」。表示每日二十四小時、每週七日，通常寫成 24/7。 由於修改涉及數字，系統必須確認這不是原作者真正想寫的數值 247。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0009-I020', 'I020', 'PARA-0009-S10', 1, 'family gathering', 'family gatherings', 1, 'NOUN_RECURRING_FAMILY_GATHERING_PLURAL', '「family gathering」在此應改為「family gatherings」。gathering 是單數可數名詞，不能在沒有冠詞或其他限定詞的情況下單獨使用。這裡泛指家庭聚會，所以用複數 family gatherings。', '[]'::jsonb, 0.9, 'approved'
