select '2026-08-02.1', 'PARA-0009-I022', 'I022', 'PARA-0009-S10', 3, 'stay behind for work', 'stay behind at work', 1, 'PREP_STAY_BEHIND_AT_WORK', '「stay behind for work」在此應改為「stay behind at work」。表示下班時間後仍留在工作場所，可寫 stay behind at work。stay behind for a meeting 則表示為了參加會議而留下，當中 for 引出目的。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0009-I023', 'I023', 'PARA-0009-S10', 4, 'devote less time in social activities', 'devote less time to social activities', 1, 'PREP_DEVOTE_TIME_TO', '「devote less time in social activities」在此應改為「devote less time to social activities」。devote time 後面使用 to，所以寫 devote less time to social activities。spendless time in social activities 在部分語境可用 in，但動詞換成 devote 後便要使用 to。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0009-I024', 'I024', 'PARA-0009-S11', 1, 'draws on negative effects to', 'has negative effects on', 1, 'COLLOC_HAVE_EFFECTS_ON', '「draws on negative effects to」在此應改為「has negative effects on」。have negative effects on + 人／事物是標準搭配。 draw on 表示利用資源或經驗，例如 draw on previous research，不能用來表示造成負面影響。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0009-I025', 'I025', 'PARA-0009-S12', 1, 'their working efficiency', 'workers'' working efficiency', 1, 'PRONOUN_AMBIGUOUS_POSSESSIVE_EXPLICIT_WORKERS', '「their working efficiency」在此應改為「workers'' working efficiency」。their 可能指 employers、 workers 或前面的 some，指涉不清。根據論點，原意似乎是工人的工作效率，因此明確寫成 workers''working efficiency。若原意是僱主的效率，則應保留另一個版本。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
