insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0010-I008', 'I008', 'PARA-0010-S05', 2, 'Wearing uniform', 'wearing a uniform', 1, 'ARTICLE_SINGULAR_COUNT_UNIFORM_IN_GERUND', '「Wearing uniform」在此應改為「wearing a uniform」。uniform 是單數可數名詞，要加 a。加入 is that 後， wearing 不再位於句首，因此改用小寫。', '[]'::jsonb, 0.9, 'approved'
