insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0010-I009', 'I009', 'PARA-0010-S05', 3, 'this wearing anxiety', 'anxiety about clothing', 1, 'COLLOC_ANXIETY_ABOUT_CLOTHING', '「this wearing anxiety」在此應改為「anxiety about clothing」。anxiety 通常用 about 或 over 引出令人憂慮的事情。 wearing anxiety 不能清楚表達「對衣着的焦慮」。也可寫 clothing-related anxiety。', '[]'::jsonb, 0.9, 'approved'
