insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0010-I010', 'I010', 'PARA-0010-S06', 1, 'outfits clothes', 'outfits', 1, 'NOUN_REDUNDANT_OUTFITS_CLOTHES', '「outfits clothes」在此應改為「outfits」。outfit 本身已表示一套衣服，不能把 outfits clothes 當作一般名詞組合。可保留 outfits，或改為單獨的 clothes。', '[]'::jsonb, 0.9, 'approved'
