insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0010-I051', 'I051', 'PARA-0010-S22', 3, 'comparison', 'comparison,', 1, 'PUNCT_COORDINATED_INDEPENDENT_CLAUSES_COMMA', '「comparison」在此應改為「comparison,」。school uniforms can... 和 they can cause... 都是完整主句，由 but 連接時，正式寫作通常在 but 前加逗號。', '[]'::jsonb, 0.9, 'approved'
