insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0011-I001', 'I001', 'PARA-0011-S01', 1, 'work become', 'work has become', 1, 'TENSE_PRESENT_PERFECT_CHANGE_TO_PRESENT_STATE', '「work become」在此應改為「work has become」。工作發展至今已成為生活的一部分，因此目標句使用現在完成式 has become。 work 是單數不可數主語，所以不能直接接 become。 若原意是一般規律，work becomes 也可成立，故應保留為可接受替代。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0011-I002', 'I002', 'PARA-0011-S01', 2, 'our life', 'our lives', 1, 'NOUN_DISTRIBUTIVE_POSSESSIVE_PLURAL_LIVES', '「our life」在此應改為「our lives」。our 指多個人的生活，這裡通常用複數 our lives。 在把眾人的生活視為一個整體概念時，our life asa community 也可能成立，但本句是一般個人生活。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0011-I003', 'I003', 'PARA-0011-S01', 3, 'our private time it has', 'our private time has', 1, 'CLAUSE_MAIN_SUBJECT_NO_RESUMPTIVE_PRONOUN', '「our private time it has」在此應改為「our private time has」。our private time 已經是主句主語，不能再加入代名詞 it 重複同一主語。公式：主語 + 有限動詞，不是主語 + it + 有限動詞。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0011-I004', 'I004', 'PARA-0011-S02', 1, 'over workload', 'excessive workloads,', 1, 'COLLOC_EXCESSIVE_WORKLOAD_PLURAL', '「over workload」在此應改為「excessive workloads,」。over 不能直接這樣修飾 workload。表示工作量過多，可用 an excessive workload 或泛指多種工作負擔的 excessive workloads。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0011-I005', 'I005', 'PARA-0011-S02', 2, 'leads', 'which lead', 1, 'CLAUSE_CAUSED_BY_NP_RELATIVE_RESULT', '「leads」在此應改為「which lead」。is caused 已是主句的有限動詞，後面的 leads 不能在沒有連接詞下直接形成第二個謂語。加入 which 建立關係分句；先行詞 workloads 是複數，所以用 lead。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0011-I006', 'I006', 'PARA-0011-S03', 1, 'set', 'sets', 1, 'SVA_PRESENT_SINGULAR_GOVERNMENT_S_FORM', '「set」在此應改為「sets」。the government 在本句視為單數機構，一般現在式動詞用 sets。英式英文有時可把集體名詞視為複數，但本句聚焦政府作為一個政策制定者。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0011-I007', 'I007', 'PARA-0011-S03', 2, 'limits maximum working hour', 'maximum limit on working hours', 1, 'NOUN_MAXIMUM_LIMIT_ON_WORKING_HOURS', '「limits maximum working hour」在此應改為「maximum limit on working hours」。a 後面要接單數 limit； maximum 放在名詞前；表示對某事設定上限，用 a limit on + 名詞。這裡泛指每週或每日工時，所以用複數 working hours。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0011-I008', 'I008', 'PARA-0011-S03', 3, 'and', 'and employees', 1, 'CLAUSE_COORDINATED_IF_CLAUSES_EXPLICIT_SUBJECT', '「and」在此應改為「and employees」。第一個動作由 the government 執行，第二個動作則按原意由 employees 執行。主語不同時，不能讓兩個動詞錯誤地共用同一主語，因此要明確補上 employees。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0011-I009', 'I009', 'PARA-0011-S03', 4, 'boundaries', 'boundaries, these measures', 1, 'CLAUSE_FRONTED_IF_MAIN_CLAUSE_SUBJECT', '「boundaries」在此應改為「boundaries, these measures」。句首 If... 部分是條件分句，之後仍需要一個完整主句。原文只有 can protect，欠缺主語；目標句加入 these measures，並以逗號分隔條件分句。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0011-I010', 'I010', 'PARA-0011-S03', 5, 'employees', 'employees''', 1, 'POSSESSIVE_REGULAR_PLURAL_APOSTROPHE', '「employees」在此應改為「employees''」。work–life balance 屬於多名 employees。規則複數名詞已以 s 結尾，所以在 s 後加撇號： employees''。', '[]'::jsonb, 0.9, 'approved'
