insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0011-I032', 'I032', 'PARA-0011-S13', 4, 'punish or give them bad reviews', 'punish them or give them bad reviews', 1, 'PARALLEL_TRANSITIVE_VERBS_EXPLICIT_OBJECT', '「punish or give them bad reviews」在此應改為「punish them or give them bad reviews」。punish 是及物動詞，需要受詞。後面的 them 是 give 的間接受詞，不能自動倒推為 punish 的受詞，因此要明確寫 punish them。', '[]'::jsonb, 0.9, 'approved'
