select '2026-08-02.1', 'PARA-0011-I038', 'I038', 'PARA-0011-S16', 1, 'examples', 'example', 1, 'FIXED_FOR_EXAMPLE_SINGULAR', '「examples」在此應改為「example」。固定連接語使用單數 For example。', '[]'::jsonb, 0.9, 'approved'
