select '2026-08-02.1', 'PARA-0011-I045', 'I045', 'PARA-0011-S19', 3, 'work condition', 'working conditions', 1, 'NOUN_WORKING_CONDITIONS_PLURAL', '「work condition」在此應改為「working conditions」。固定名詞詞組通常是 working conditions，並以複數泛指工時、待遇及環境等多方面條件。改為複數後，不再使用單數冠詞 a。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0011-I046', 'I046', 'PARA-0011-S19', 4, 'rests', 'rest', 1, 'NOUN_THE_REST_OF_SINGULAR_REST', '「rests」在此應改為「rest」。表示剩餘部分時，固定結構是 the rest of + 名詞， 其中 rest 保持單數。 rests 可作動詞或表示多次休息，但不適用於此結構。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
