insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0012-I005', 'I005', 'PARA-0012-S02', 3, 'stores and enhanced', 'stores, and uniforms enhance', 1, 'CLAUSE_COORDINATED_MISSING_SUBJECT_FINITE_VERB', '「stores and enhanced」在此應改為「stores, and uniforms enhance」。customers can locate staff 已是完整分句； enhanced 不能在沒有主語的情況下直接與它並列。第二個意思是制服提升信任和專業形象，因此補回主語 uniforms，並用一般現在式 enhance。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0012-I006', 'I006', 'PARA-0012-S03', 1, 'In staff opinion', 'In the staff''s opinion', 1, 'POSSESSIVE_COLLECTIVE_STAFF_OPINION', '「In staff opinion」在此應改為「In the staff''s opinion」。固定結構是 in someone ''s opinion。這裡的 opinion 屬於 staff，因此使用定冠詞和所有格：in the staff''s opinion。也可寫 in the opinion of the staff。', '[]'::jsonb, 0.9, 'approved'
