insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0012-I007', 'I007', 'PARA-0012-S03', 2, 'can doesn’t required', 'can reduce', 1, 'MODAL_NEGATION_SINGLE_AUXILIARY_BASE_VERB', '「can doesn’t required」在此應改為「can reduce」。一個動詞組不能同時使用 can 和 doesn''t 來控制同一個主要動詞；can 後面亦只能接動詞原形。按上下文，作者想表達制服可減少開支，因此改為 can reduce。 若原意是「不需要另外購買衣服」，另一個正確寫法是 means that staff do not need a separate work wardrobe。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
