insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0012-I035', 'I035', 'PARA-0012-S08', 13, 'wearing uniform', 'are wearing a uniform', 1, 'CLAUSE_NO_STAFF_BE_PROGRESSIVE_ARTICLE', '「wearing uniform」在此應改為「are wearing a uniform」。關係分句需要有限動詞，所以在 wearing 前加入 are。 uniform 是單數可數名詞，前面需要冠詞 a。本句把 staff 視為多名員工，因此使用 are。', '[]'::jsonb, 0.9, 'approved'
