insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0013-I005', 'I005', 'PARA-0013-S02', 3, 'Italy', 'Italy''s', 1, 'COMP_POPULATION_POSSESSIVE_ELLIPSIS', '「Italy」在此應改為「Italy''s」。前面比較的是 Yemen''s population，所以後面也要比較 Italy 的人口，而不是把人口直接與國家比較。 Italy''s 省略了重複的 population。公式： A''s population is younger than B''s.', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0013-I006', 'I006', 'PARA-0013-S02', 4, 'this', 'and this', 1, 'PUNCT_COMMA_SPLICE_COORDINATOR_AND', '「this」在此應改為「and this」。前後都是完整主句，不能只用逗號連接。加入 and 後，兩個主句形成正確的並列結構。分號或句號也是可接受替代。', '[]'::jsonb, 0.9, 'approved'
