insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0013-I007', 'I007', 'PARA-0013-S02', 5, 'pattern', 'contrast', 1, 'WORDCHOICE_CONTRAST_NOT_PATTERN', '「pattern」在此應改為「contrast」。本句描述的是兩國人口年齡結構之間的差異，因此 contrast 較能準確指回前面的比較。 pattern 本身不是文法錯誤，但未清楚表示哪一種模式正在改變。', '[]'::jsonb, 0.9, 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;
insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0013-I008', 'I008', 'PARA-0013-S02', 6, 'keep diversifying', 'is expected to become more pronounced', 1, 'TENSE_PROJECTION_EXPECTED_TO_BECOME', '「keep diversifying」在此應改為「is expected to become more pronounced」。diversify 通常表示種類變得更多，不適合直接描述兩國差異擴大。 2050 年亦是預測數據，因此使用 is expected to + 動詞原形。若原意只是差異持續存在，也可寫 is expected to continue。', '[]'::jsonb, 0.9, 'approved'
