insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0013-I030', 'I030', 'PARA-0013-S11', 2, 'has nearly remain unchanged', 'is projected to remain relatively stable', 1, 'TENSE_PROJECTION_REMAIN_STABLE', '「has nearly remain unchanged」在此應改為「is projected to remain relatively stable」。has 後面本應使用過去分詞 remained，但本句包含 2050 年預測，因此現在完成式亦不合適。目標句使用 is projected to remain。 relatively stable 也容許比例有輕微變化。', '[]'::jsonb, 0.9, 'approved'
