insert into public.writing_grammar_issues (corpus_version, issue_id, source_issue_id, sentence_id, issue_order, wrong_text, replacement_text, occurrence_index, rule_id, explanation_zh_hant, acceptable_alternatives, confidence, status)
select '2026-08-02.1', 'PARA-0014-I006', 'I006', 'PARA-0014-S05', 1, 'records need to digitise', 'records need to be digitised', 1, 'INFINITIVE_NEED_PASSIVE_TO_BE_PARTICIPLE', '「records need to digitise」在此應改為「records need to be digitised」。records 是被數碼化的事物，所以要用被動不定詞： need to be + 過去分詞。另一個正確寫法是 The staff need to digitise the records.', '[]'::jsonb, 0.9, 'approved'
