insert into public.writing_grammar_rule_exceptions (corpus_version, exception_id, rule_id, exception_order, condition_en, example_text, explanation_zh_hant, english_variant, status)
select '2026-08-02.1', 'EX-PAST_TENSE_PARALLEL-01', 'PAST_TENSE_PARALLEL', 1, 'A modal changes the required form of the following verb.', 'The journey may broaden our knowledge.', '情態動詞 may 後面使用動詞原形，所以這裡的 broaden 正確。', 'both', 'approved'
where exists (select 1 from public.writing_grammar_corpus_releases where corpus_version = '2026-08-02.1' and status = 'reviewed') on conflict do nothing;

do $$
begin
  if (select count(*) from public.writing_grammar_corpus_groups where corpus_version = '2026-08-02.1') <> 18
    or (select count(*) from public.writing_grammar_paragraphs where corpus_version = '2026-08-02.1') <> 18
    or (select count(*) from public.writing_grammar_sentences where corpus_version = '2026-08-02.1') <> 322
    or (select count(*) from public.writing_grammar_issues where corpus_version = '2026-08-02.1') <> 724
    or (select count(*) from public.writing_grammar_rules where corpus_version = '2026-08-02.1') <> 640
    or (select count(*) from public.writing_grammar_rule_exceptions where corpus_version = '2026-08-02.1') <> 13
  then
    raise exception 'Corpus seed counts do not match the approved release';
  end if;
end;
$$;

update public.writing_grammar_corpus_releases set status = 'approved', is_current = true, approved_at = '2026-08-02T00:00:00.000Z'::timestamptz where corpus_version = '2026-08-02.1' and status = 'reviewed';
update public.writing_grammar_corpus_releases set is_current = true where corpus_version = '2026-08-02.1' and status = 'approved' and not is_current;

commit;
